// ChainConnectV2 contract configuration.
// Address + ABI come from src/contracts/deployment.json, which is generated by
// `npm run deploy:testnet` in /blockchain. Do not hand-edit them here.
import deployment from '../contracts/deployment.json';

export const CHAIN_CONNECT_V2_ADDRESS: string = deployment.chainConnectV2.address;
export const CHAIN_CONNECT_V2_ABI: any = deployment.chainConnectV2.abi;

// Helper function to get job status string
export function getJobStatusFromNumber(status: number): string {
  const statuses = ['Created', 'Funded', 'InProgress', 'Completed', 'Released', 'Refunded'];
  return statuses[status] || 'Unknown';
}

// Helper to get level name
export function getLevelName(level: number): string {
  const levels: { [key: number]: string } = {
    1: 'Beginner',
    2: 'Pro',
    3: 'Expert'
  };
  return levels[level] || 'Unknown';
}
